import{c as l,Q as t,j as i,m as r}from"./chunks/framework.BPKcPtvA.js";const s="/screenshots/background-tasks-topbar.png",e="/screenshots/background-tasks-sidebar.png",o="/screenshots/background-tasks-panel.png",k=JSON.parse('{"title":"バックグラウンドタスク","description":"","frontmatter":{},"headers":[],"relativePath":"guide/background-tasks.md","filePath":"guide/background-tasks.md","lastUpdated":1786391114000}'),n={name:"guide/background-tasks.md"};function c(d,a,p,u,g,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="バックグラウンドタスク" tabindex="-1">バックグラウンドタスク <a class="header-anchor" href="#バックグラウンドタスク" aria-label="Permalink to &quot;バックグラウンドタスク&quot;">​</a></h1><h2 id="どこから確認する" tabindex="-1">どこから確認する？ <a class="header-anchor" href="#どこから確認する" aria-label="Permalink to &quot;どこから確認する？&quot;">​</a></h2><p>画面の <strong>「バックグラウンドタスク」</strong> ボタンを押すと、現在動いている処理と 進み具合、アプリを開いてから終わった処理の履歴を確認できます。未完了の処理があると、 ボタンに現在一覧に残っている大もとの処理数が表示されます。一時停止中の処理も この件数に含まれますが、動作中を示す表示は止まります。</p><ul><li><p><strong>通常の上部タブ表示</strong> — 画面右上の「…」メニューボタンの左にあります。</p><p><img src="'+s+'" alt="上部タブ表示のバックグラウンドタスクボタン"></p></li><li><p><strong>サイドバー表示</strong> — 左側アイコンバー下部の「…」メニューボタンの上にあります。</p><p><img src="'+e+'" alt="サイドバー表示のバックグラウンドタスクボタン"></p></li></ul><p>ボタンにマウスポインターを重ねると「バックグラウンドタスク」と表示されます。</p><h2 id="親タスクと子タスク" tabindex="-1">親タスクと子タスク <a class="header-anchor" href="#親タスクと子タスク" aria-label="Permalink to &quot;親タスクと子タスク&quot;">​</a></h2><p>ライブラリ更新のように複数の手順を順番に行う処理は、<strong>大もとの親タスク</strong>と <strong>その中の子タスク</strong>に分けて表示します。たとえばライブラリ更新では、新しい購入品の 確認、注文情報の補完、商品情報の更新を同じまとまりとして確認できます。</p><p><img src="'+o+'" alt="親子で表示されたバックグラウンドタスク"></p><ul><li>親行には「2/3 ステップ」のような全体の進み具合と、現在の子タスクを表示します。</li><li>親の矢印で子タスクを折りたためます。折りたたんでも現在の子タスク名は親行に残ります。</li><li>更新や解析で繰り返し処理する商品・ファイルは一件ずつ行にせず、 「12/40 件」のように進捗で表示します。個別に操作できるダウンロードだけは、 1 ファイルを 1 タスクとして表示します。</li><li>実行されなかった子タスクは「スキップ」と表示され、pill にカーソルを合わせると 理由を確認できます。</li><li>終わった子タスクは親処理が終わるまで残り、その後も親子のまとまりごと履歴で確認できます。</li></ul><h2 id="終わった処理の履歴" tabindex="-1">終わった処理の履歴 <a class="header-anchor" href="#終わった処理の履歴" aria-label="Permalink to &quot;終わった処理の履歴&quot;">​</a></h2><p>完了・失敗・中止済みのダウンロードは最新 200 件まで、その他の大もとの処理は アプリを終了するまで履歴としてパネルに残ります。</p><ul><li>一覧には実行中の処理、一時停止中の処理、履歴の順で表示されます。</li><li>履歴はボタンの件数に含まれません。バッジは未完了の大もとの処理数を示します。</li><li>履歴は保存されません。アプリを再起動すると空になります。</li></ul><h2 id="中止する" tabindex="-1">中止する <a class="header-anchor" href="#中止する" aria-label="Permalink to &quot;中止する&quot;">​</a></h2><ul><li>親の <strong>「中止」</strong> は、現在の子タスクに中止を依頼し、まだ始まっていない 子タスクも開始しないようにします。</li><li>子の <strong>「中止」</strong> はその子だけを中止します。親とほかの子タスクは続行します。</li><li>ファイル保存やアーカイブ作成などを壊さないため、中止を押してから安全な区切りで 止まるまで「中止中」と表示されることがあります。</li></ul><p>ダウンロードもファイルごとのタスクとして表示され、進捗の確認と中止ができます。 ただし <strong>解凍中</strong> は、展開先を壊さないようにするため中止できません。解凍が完了するまで お待ちください。 一時停止・再開、待機順の並べ替え、同時ダウンロード数の変更は、ライブラリ画面の <strong>ダウンロードキュー</strong>から行ってください。</p><h2 id="表示される主な処理" tabindex="-1">表示される主な処理 <a class="header-anchor" href="#表示される主な処理" aria-label="Permalink to &quot;表示される主な処理&quot;">​</a></h2><ul><li>起動時のライブラリ・ショップ・スキリスト更新</li><li>手動のライブラリ商品情報更新</li><li>BOOTH スキリスト同期</li><li>フォロー中ショップ同期</li><li>ファイルのダウンロードと展開</li><li>重複ファイル用ハッシュ計算</li><li>アーカイブ／アーカイブ解除</li><li>ストレージ最適化の解析・適用</li><li>複数 Unity Package の結合</li></ul>',17)])])}const m=l(n,[["render",c]]);export{k as __pageData,m as default};
